BEGIN;
CREATE TABLE IF NOT EXISTS sm_organizations (id BIGSERIAL PRIMARY KEY, tenant_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sm_memberships (organization_id BIGINT NOT NULL REFERENCES sm_organizations(id), user_id BIGINT NOT NULL, role TEXT NOT NULL CHECK(role IN ('worker','supervisor','safety_manager','admin')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS sm_sites (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES sm_organizations(id), name TEXT NOT NULL, timezone TEXT NOT NULL, emergency_plan_version TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sm_devices (id TEXT PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES sm_organizations(id), site_id BIGINT NOT NULL REFERENCES sm_sites(id), assigned_worker_id BIGINT, secret_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','quarantined','retired')), last_seen_at TIMESTAMPTZ, firmware_version TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sm_device_nonces (device_id TEXT NOT NULL REFERENCES sm_devices(id), nonce TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(device_id,nonce));
CREATE TABLE IF NOT EXISTS sm_readings (id BIGSERIAL PRIMARY KEY, device_id TEXT NOT NULL REFERENCES sm_devices(id), site_id BIGINT NOT NULL REFERENCES sm_sites(id), observed_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), reading_type TEXT NOT NULL, reading_value NUMERIC NOT NULL, unit TEXT, quality TEXT NOT NULL CHECK(quality IN ('valid','degraded','invalid')), raw_payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS sm_hazards (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL, site_id BIGINT NOT NULL REFERENCES sm_sites(id), source TEXT NOT NULL CHECK(source IN ('worker','inspection','device','import')), severity TEXT NOT NULL CHECK(severity IN ('low','medium','high','critical')), description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','controlled','closed')), assigned_to BIGINT, opened_at TIMESTAMPTZ NOT NULL DEFAULT now(), closed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS sm_alerts (id BIGSERIAL PRIMARY KEY, hazard_id BIGINT REFERENCES sm_hazards(id), site_id BIGINT NOT NULL, rule_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered','acknowledged','failed')), delivery_attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sm_corrective_actions (id BIGSERIAL PRIMARY KEY, hazard_id BIGINT NOT NULL REFERENCES sm_hazards(id), description TEXT NOT NULL, owner_id BIGINT NOT NULL, due_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed','verified')), completed_at TIMESTAMPTZ, verified_by BIGINT);
CREATE TABLE IF NOT EXISTS sm_closure_evidence (id BIGSERIAL PRIMARY KEY, hazard_id BIGINT NOT NULL REFERENCES sm_hazards(id), storage_key TEXT NOT NULL, sha256 TEXT NOT NULL, note TEXT NOT NULL, captured_at TIMESTAMPTZ NOT NULL, uploaded_by BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sm_incident_audit (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL, site_id BIGINT, actor_type TEXT NOT NULL CHECK(actor_type IN ('user','device','system')), actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details JSONB, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION sm_block_incident_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'safety incident records cannot be deleted'; END $$;
DROP TRIGGER IF EXISTS sm_hazard_no_delete ON sm_hazards;
CREATE TRIGGER sm_hazard_no_delete BEFORE DELETE ON sm_hazards FOR EACH ROW EXECUTE FUNCTION sm_block_incident_delete();
COMMIT;
